//go:build e2e

package tests

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/entireio/cli/e2e/agents"
	"github.com/entireio/cli/e2e/entire"
	"github.com/entireio/cli/e2e/testutil"
)

func TestMain(m *testing.M) {
	runDir := os.Getenv("E2E_ARTIFACT_DIR")
	if runDir == "" {
		_, file, _, _ := runtime.Caller(0)
		testutil.ArtifactRoot = filepath.Join(filepath.Dir(file), "..", "artifacts")
		runDir = testutil.ArtifactRunDir()
	}
	_ = os.MkdirAll(runDir, 0o755)
	testutil.SetRunDir(runDir)

	// Route every spawned entire binary (and the git hooks that invoke it) at
	// the file-backed token store so e2e never touches the developer's real
	// OS keychain. internal/entireclient/tokenstore honors these env vars
	// unconditionally, and they are inherited by child processes.
	// In-process keyring.MockInit() cannot help here: the binary is a subprocess.
	os.Setenv("ENTIRE_TOKEN_STORE", "file")
	os.Setenv("ENTIRE_TOKEN_STORE_PATH", filepath.Join(runDir, "e2e-tokenstore.json"))

	// Same for the CLI's config and cache directories: contexts.json,
	// version_check.json, and the discovery caches must never resolve to the
	// developer's real ~/.config/entire or ~/.cache/entire from a spawned
	// binary (testing.Testing() is false there, so the internal/testdirs
	// fallback cannot protect it).
	os.Setenv("ENTIRE_CONFIG_DIR", filepath.Join(runDir, "entire-config"))
	os.Setenv("XDG_CACHE_HOME", filepath.Join(runDir, "entire-cache"))

	// Select the checkpoint storage backend for the whole suite. E2E_CHECKPOINT_STORE
	// (e.g. "git-refs") maps to the ENTIRE_CHECKPOINTS_PRIMARY override the spawned
	// binary honors, so every condensation/read/push in the run exercises that
	// backend. Unset pins git-branch: the harness's backend-aware assertions
	// (testutil.checkpointStoreMode) default to the v1 branch while first-run
	// enable now defaults new setups to git-refs — without the pin the binary
	// writes refs and every branch-shaped assertion times out. The env also
	// suppresses that first-run settings write.
	store := os.Getenv("E2E_CHECKPOINT_STORE")
	if store == "" {
		store = "git-branch"
	}
	os.Setenv("ENTIRE_CHECKPOINTS_PRIMARY", store)

	// Resolve the entire binary (set by mise run build via E2E_ENTIRE_BIN).
	entireBin := entire.BinPath()
	if err := ensureHookEntireBinary(entireBin); err != nil {
		fmt.Fprintf(os.Stderr, "preflight: prepare hook entire binary: %v\n", err)
		os.Exit(1)
	}

	// Prepend the binary's directory to PATH so that git hooks and agent
	// hooks (which call bare "entire") resolve to the same binary the test
	// harness uses, not a system-installed one.
	os.Setenv("PATH", filepath.Dir(entireBin)+string(os.PathListSeparator)+os.Getenv("PATH"))

	// Preflight: verify required dependencies before running any tests.
	// tmux is only required on Unix (interactive session tests are skipped on Windows).
	var missing []string
	requiredBins := []string{"git"}
	if runtime.GOOS != "windows" {
		requiredBins = append(requiredBins, "tmux")
	}
	for _, bin := range requiredBins {
		if _, err := exec.LookPath(bin); err != nil {
			missing = append(missing, bin)
		}
	}
	for _, a := range agents.All() {
		if _, err := exec.LookPath(a.Binary()); err != nil {
			missing = append(missing, fmt.Sprintf("%s (%s)", a.Binary(), a.Name()))
		}
	}
	if len(missing) > 0 {
		fmt.Fprintf(os.Stderr, "preflight: missing required binaries: %v\n", missing)
		os.Exit(1)
	}

	version := "unknown"
	if out, err := exec.Command(entireBin, "version").Output(); err == nil {
		version = string(out)
	}

	// Write preflight info to artifact dir only — gotestsum swallows both
	// stdout and stderr, so the test-e2e script cats this file at the end.
	preflight := fmt.Sprintf("entire binary:  %s\nentire version: %s\n",
		entireBin, version)
	_ = os.WriteFile(filepath.Join(runDir, "entire-version.txt"), []byte(preflight), 0o644)

	// Don't look at user's Git config, ignore everything except the project-local Git settings.
	// This avoids oddball configs in ~/.gitconfig messing with our E2E tests.
	// We use an empty temp file instead of os.DevNull because git on Windows
	// cannot open NUL as a config file ("unable to access 'NUL': Invalid argument").
	emptyConfig := filepath.Join(runDir, "empty-gitconfig")
	_ = os.WriteFile(emptyConfig, nil, 0o644)
	os.Setenv("GIT_CONFIG_GLOBAL", emptyConfig)

	os.Exit(m.Run())
}

func ensureHookEntireBinary(entireBin string) error {
	dir := filepath.Dir(entireBin)
	hookName := "entire"
	if runtime.GOOS == "windows" {
		hookName = "entire.exe"
	}
	hookBin := filepath.Join(dir, hookName)
	if filepath.Clean(entireBin) == filepath.Clean(hookBin) {
		return nil
	}

	_ = os.Remove(hookBin)

	if runtime.GOOS == "windows" {
		data, err := os.ReadFile(entireBin)
		if err != nil {
			return err
		}
		return os.WriteFile(hookBin, data, 0o755)
	}

	return os.Symlink(entireBin, hookBin)
}

	var b strings.Builder
	if len(data) > 0 {
		b.Write(data)
		if data[len(data)-1] != '\n' {
			b.WriteByte('\n')
		}
	}
	b.WriteString(entry)
	b.WriteByte('\n')

	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
	}
	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", excludePath, err)
	}
	return nil
}

// ForEachAgent runs fn as a parallel subtest for every registered agent.
// It handles repo setup, concurrency gating, context timeout, and cleanup.
// The timeout is scaled by each agent's TimeoutMultiplier.
//
// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
// panic and restarts the entire scenario with a fresh repository, up to
// maxScenarioRestarts times. This avoids stale CLI session state from the
// failed attempt poisoning the retry.
func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
	t.Helper()
	t.Parallel()
	all := agents.All()
	if len(all) == 0 {
		t.Skip("no agents registered (check E2E_AGENT filter)")
	}
	runForAgents(t, all, timeout, fn)
}

// ForEachNamedAgent runs fn as a parallel subtest for each registered agent
// whose name matches one of the provided names.
func ForEachNamedAgent(t *testing.T, timeout time.Duration, names []string, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
	t.Helper()
	t.Parallel()

	allowed := make(map[string]struct{}, len(names))
	for _, name := range names {
		allowed[name] = struct{}{}
	}

	var selected []agents.Agent
	for _, agent := range agents.All() {
		if _, ok := allowed[agent.Name()]; ok {
			selected = append(selected, agent)
		}
	}
	if len(selected) == 0 {
		t.Skip("no matching agents registered (check E2E_AGENT filter)")
	}

	runForAgents(t, selected, timeout, fn)
}

func runForAgents(t *testing.T, all []agents.Agent, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
	t.Helper()
	for _, agent := range all {
		t.Run(agent.Name(), func(t *testing.T) {
			// Use the global test deadline for slot wait so we don't
			// skip prematurely — only bail if the whole binary is dying.
			slotCtx := context.Background()
			if deadline, ok := t.Deadline(); ok {
				var cancel context.CancelFunc
				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
				defer cancel()
			}
			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
				t.Fatalf("timed out waiting for agent slot: %v", err)
			}
			defer agents.ReleaseSlot(agent)

			// Per-test timeout starts after slot is acquired, scaled
			// by the agent's multiplier (e.g. 2.5× for gemini).
			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())

			var prevState *RepoState
			for attempt := range maxScenarioRestarts + 1 {
				s := SetupRepo(t, agent)
				ctx, cancel := context.WithTimeout(context.Background(), scaled)

				// On restart, suppress artifact capture from the previous
				// failed attempt so it doesn't overwrite the final one.
				if prevState != nil {
					prevState.skipArtifacts = true
				}

				restarted := runScenario(t, s, ctx, fn)
				cancel()

				if !restarted {
					return
				}
				prevState = s
				if attempt >= maxScenarioRestarts {
					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
				}
				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
			}
		})
	}
}

// runScenario runs the test function and recovers from errScenarioRestart
// panics triggered by transient API errors in RunPrompt. Returns true if
// the scenario should be restarted with a fresh repository.
func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
	t.Helper()
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(errScenarioRestart); ok {
				restarted = true
				return
			}
			panic(r) // re-panic for unexpected panics
		}
	}()
	fn(t, s, ctx)
	return false
}

const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts

// errScenarioRestart is panicked by RunPrompt when a transient API error is
// detected. ForEachAgent recovers from this panic and restarts the test
// scenario with a fresh repository, avoiding stale CLI state from the failed
// attempt.
type errScenarioRestart struct {
	msg string
}

// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
// and returns the result. If the agent reports a transient API error, it
// panics with errScenarioRestart to trigger a full scenario restart in
// ForEachAgent (see runScenario).
func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
	t.Helper()
	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
	s.logPromptResult(out)

	if err != nil && s.Agent.IsTransientError(out, err) {
		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
		t.Logf("%s — restarting scenario", errMsg)
		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
		panic(errScenarioRestart{msg: errMsg})
	}

	return out, err
}

func (s *RepoState) logPromptResult(out agents.Output) {
	s.ConsoleLog.WriteString("> " + out.Command + "\n")
	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
}

// Git runs a git command in the repo and logs it to ConsoleLog.
func (s *RepoState) Git(t *testing.T, args ...string) {
	t.Helper()
	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
	Git(t, s.Dir, args...)
}

// StartSession starts an interactive session and registers it for pane
// capture in artifacts. Returns nil if the agent does not support interactive
// mode. The session is closed automatically during test cleanup.
func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
	t.Helper()
	session, err := s.Agent.StartSession(ctx, s.Dir)
	if err != nil {
		t.Fatalf("start session: %v", err)
	}
	if session == nil {
		return nil
	}
	s.session = session
	return session
}

// WaitFor waits for a pattern in the interactive session's pane and logs the
// pane content to ConsoleLog after the wait completes (success or failure).
func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
	t.Helper()
	content, err := session.WaitFor(pattern, timeout)
	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
	if err != nil {
		t.Fatalf("WaitFor(%q): %v", pattern, err)
	}
}

// IsExternalAgent returns true if the agent implements the ExternalAgent
// interface and reports itself as external.
func (s *RepoState) IsExternalAgent() bool {
	ea, ok := s.Agent.(agents.ExternalAgent)
	return ok && ea.IsExternalAgent()
}

// Send sends input to an interactive session and logs it to ConsoleLog.
// Fails the test on error.
func (s *RepoState) Send(t *testing.T, session agents.Session, input string) {
	t.Helper()
	s.ConsoleLog.WriteString("> send: " + input + "\n")
	if err := session.Send(input); err != nil {
		t.Fatalf("send failed: %v", err)
	}
}

// PatchSettings merges extra keys into .entire/settings.json.
func PatchSettings(t *testing.T, dir string, extra map[string]any) {
	t.Helper()
	path := filepath.Join(dir, ".entire", "settings.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read settings: %v", err)
	}
	var settings map[string]any
	if err := json.Unmarshal(data, &settings); err != nil {
		t.Fatalf("parse settings: %v", err)
	}
	mergeSettings(settings, extra)
	out, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		t.Fatalf("marshal settings: %v", err)
          # Don't persist the (copilot-scoped) GITHUB_TOKEN in .git/config, where
          # an agent process running in the checkout could read it.
          persist-credentials: false

      - name: Setup mise
        uses: jdx/mise-action@f10502fc09dadecfefb962fff68ce77213930204 # v4

      - name: Install system dependencies
        run: sudo apt-get update && sudo apt-get install -y tmux

      - name: Install agent CLI
        run: |
          case "${{ matrix.agent }}" in
            claude-code) curl -fsSL https://claude.ai/install.sh | bash ;;
            opencode)    curl -fsSL https://opencode.ai/install | bash ;;
            gemini-cli)  npm install -g @google/gemini-cli ;;
            codex)       npm install -g @openai/codex ;;
            cursor-cli)  curl https://cursor.com/install -fsS | bash ;;
            factoryai-droid) curl -fsSL https://app.factory.ai/cli | sh ;;
            copilot-cli)  npm install -g @github/copilot  ;;
            roger-roger) ;; # installed by mise (see mise.toml)
          esac
          echo "$HOME/.local/bin" >> $GITHUB_PATH

      - name: Verify roger-roger agent
        if: matrix.agent == 'roger-roger'
        run: |
          set -euo pipefail
          echo "Verifying roger-roger binaries on PATH..."
          command -v roger-roger
          command -v entire-agent-roger-roger

      - name: Bootstrap agent
        if: matrix.agent != 'roger-roger'
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
          CURSOR_API_KEY: ${{ secrets.CURSOR_API_KEY }}
          FACTORY_API_KEY: ${{ secrets.FACTORY_API_KEY }}
          # Only the copilot-cli leg gets the token; other agents must not receive it.
          COPILOT_GITHUB_TOKEN: ${{ matrix.agent == 'copilot-cli' && github.token || '' }}
        run: go run ./e2e/bootstrap

      - name: Run E2E Tests
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
          E2E_CODEX_MODEL: ${{ matrix.agent == 'codex' && 'gpt-5.4-mini' || '' }}
          E2E_GEMINI_MODEL: ${{ matrix.agent == 'gemini-cli' && 'gemini-3.1-flash-lite' || '' }}
          CURSOR_API_KEY: ${{ secrets.CURSOR_API_KEY }}
          FACTORY_API_KEY: ${{ secrets.FACTORY_API_KEY }}
          # Only the copilot-cli leg gets the token; other agents must not receive it.
          COPILOT_GITHUB_TOKEN: ${{ matrix.agent == 'copilot-cli' && github.token || '' }}
          E2E_CONCURRENT_TEST_LIMIT: ${{ matrix.agent == 'gemini-cli' && '6' || matrix.agent == 'factoryai-droid' && '1' || matrix.agent == 'cursor-cli' && '2' || '' }}
        # roger-roger is deterministic, so it runs through its dedicated task,
        # which does NOT enable --rerun-fails. Routing it through the default
        # task (`test:e2e`) would retry a real regression and mask it.
        run: |
          if [ "${{ matrix.agent }}" = "roger-roger" ]; then
            mise run test:e2e:roger-roger TestExternalAgent
          else
            mise run test:e2e --agent ${{ matrix.agent }}
          fi

      - name: Upload artifacts
        if: always()
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7
        with:
          name: e2e-artifacts-${{ matrix.agent }}
          path: e2e/artifacts/
          retention-days: 7

  e2e-windows:
    uses: ./.github/workflows/e2e-windows.yml

