package agents

import "testing"

// trustDialogPane is a trimmed capture of Copilot v1.0.63's interactive
// startup dialog. Note the footer renders the navigation hint lowercase
// ("enter to select") and the selected option uses the same "❯" cursor as the
// input prompt — the exact shape that broke the old exact-case detection.
const trustDialogPane = `╭───────────────────────────────────────────────────────────╮
│ Confirm folder trust                                        │
│                                                             │
│ /tmp/e2e-repo-457367550                                     │
│                                                             │
│ Copilot can read files in this folder and, with your        │
│ permission, edit them or run code and shell commands.       │
│                                                             │
│ Do you trust the files in this folder?                      │
│                                                             │
│ ❯ 1. Yes                                                    │
│   2. Yes, and remember this folder for future sessions      │
│   3. No (Esc)                                               │
│                                                             │
│ ↑/↓ to navigate · enter to select · esc to cancel           │
╰───────────────────────────────────────────────────────────╯`

// interactivePromptPane is the real idle prompt: a bare "❯" with no dialog
// chrome. This must NOT be classified as a startup dialog.
const interactivePromptPane = ` Tip: /app
 /tmp/e2e-repo-457367550 [master%]

❯

 / commands · ? help                                  Claude Haiku 4.5`

// TestIsStartupDialog_DetectsLowercaseTrustFooter is the regression guard for
// the Copilot v1.0.63 break: the trust dialog must be recognized even though
// its footer is lowercase ("enter to select"), so the StartSession dismissal
// loop keeps sending Enter instead of mistaking the "❯ 1. Yes" cursor for the
// interactive prompt and swallowing the first real prompt.
func TestIsStartupDialog_DetectsLowercaseTrustFooter(t *testing.T) {
	t.Parallel()
	if !isStartupDialog(trustDialogPane) {
		t.Fatal("trust dialog with lowercase footer should be detected as a startup dialog")
	}
}

// TestIsStartupDialog_DetectsByTitle confirms detection keys off the dialog
// title too, so a footer-text change in a future Copilot release does not
// silently re-break the handshake.
func TestIsStartupDialog_DetectsByTitle(t *testing.T) {
	t.Parallel()
	const titleOnly = "│ Confirm folder trust │\n│ ❯ 1. Yes │"
	if !isStartupDialog(titleOnly) {
		t.Fatal("dialog title alone should be enough to detect a startup dialog")
	}
}

// TestIsStartupDialog_IgnoresInteractivePrompt ensures the real prompt is not
// classified as a dialog — otherwise StartSession would loop dismissing a
// dialog that isn't there and never hand back a usable session.
func TestIsStartupDialog_IgnoresInteractivePrompt(t *testing.T) {
	t.Parallel()
	if isStartupDialog(interactivePromptPane) {
		t.Fatal("bare interactive prompt should not be classified as a startup dialog")
	}
}
package agents

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent/codex"
	"github.com/stretchr/testify/require"
)

// TestCodexCommandHookHash_MatchesCanonicalShape verifies the canonical
// JSON the hash is computed over, against a hand-built reference string.
// Pinning the byte-exact JSON catches drift in canonicalization (key
// sort, omit-when-nil rules, HTML-escape behavior, integer rendering)
// before it silently breaks pre-trust in e2e.
func TestCodexCommandHookHash_MatchesCanonicalShape(t *testing.T) {
	t.Parallel()
	// Reference canonical JSON for: post_tool_use, no matcher, single
	// command handler with timeout=30, async=false, no statusMessage.
	// Keys MUST be alphabetical; matcher and statusMessage MUST be absent.
	// shell-redirect characters (>) MUST NOT be HTML-escaped — Codex's
	// serde_json::to_vec passes them through unchanged.
	const wantCanonical = `{"event_name":"post_tool_use","hooks":[{"async":false,"command":"sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks codex post-tool-use'","timeout":30,"type":"command"}]}`
	sum := sha256.Sum256([]byte(wantCanonical))
	wantHash := "sha256:" + hex.EncodeToString(sum[:])

	got := codexCommandHookHash(
		"post_tool_use",
		nil, // no matcher
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks codex post-tool-use'`,
		30,
		false,
		nil, // no statusMessage
	)
	require.Equal(t, wantHash, got)
}

// TestCodexCommandHookHash_OmitsNilOptions confirms that nil matcher and
// nil statusMessage are absent from the canonical JSON — Codex's TOML
// round-trip drops Option::None, and any divergence would produce a
// different hash than what discover_handlers computes at runtime.
func TestCodexCommandHookHash_OmitsNilOptions(t *testing.T) {
	t.Parallel()
	const wantCanonical = `{"event_name":"stop","hooks":[{"async":false,"command":"echo hi","timeout":600,"type":"command"}]}`
	sum := sha256.Sum256([]byte(wantCanonical))
	wantHash := "sha256:" + hex.EncodeToString(sum[:])

	got := codexCommandHookHash("stop", nil, "echo hi", 600, false, nil)
	require.Equal(t, wantHash, got)
}

// TestCodexHookTrustState_GeneratesEntriesForEveryDeclaredHandler
// exercises the full path: read .codex/hooks.json, walk every event in
// Codex's declared order, emit a [hooks.state."<path>:<event>:0:0"] block
// per command handler with the matching trusted_hash.
func TestCodexHookTrustState_GeneratesEntriesForEveryDeclaredHandler(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	codexDir := filepath.Join(dir, ".codex")
	require.NoError(t, os.MkdirAll(codexDir, 0o750))

	hooksJSON := `{
  "hooks": {
    "SessionStart": [
      {"matcher": null, "hooks": [{"type": "command", "command": "entire hooks codex session-start", "timeout": 30}]}
    ],
    "Stop": [
      {"matcher": null, "hooks": [{"type": "command", "command": "entire hooks codex stop", "timeout": 30}]}
    ]
  }
}
`
	hooksPath := filepath.Join(codexDir, "hooks.json")
	require.NoError(t, os.WriteFile(hooksPath, []byte(hooksJSON), 0o600))

	state, err := codexHookTrustState(dir)
	require.NoError(t, err)
	require.Contains(t, state, hooksPath+":session_start:0:0")
	require.Contains(t, state, hooksPath+":stop:0:0")
	require.Contains(t, state, "trusted_hash = \"sha256:")
	// Two declared handlers → two state entries.
	require.Equal(t, 2, strings.Count(state, "[hooks.state."))
	require.Equal(t, 2, strings.Count(state, "trusted_hash ="))
}

// TestCodexHookTrustState_CoversEveryInstalledEvent guards the hand-maintained
// event table against the CLI's install set. Codex silently skips hooks with no
// trusted_hash, so an event the table doesn't know is installed but inert for
// the entire e2e suite: the hook never fires, and no test fails to say so —
// they just quietly stop covering it. SessionEnd was exactly that gap.
func TestCodexHookTrustState_CoversEveryInstalledEvent(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir) // InstallHooks falls back to cwd when there's no worktree root

	if _, err := (&codex.CodexAgent{}).InstallHooks(context.Background(), false); err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	raw, err := os.ReadFile(filepath.Join(dir, ".codex", "hooks.json"))
	require.NoError(t, err)

	// Read the events generically so the JSON shape remains the thing under test.
	var installed struct {
		Hooks map[string][]codexHookGroup `json:"hooks"`
	}
	require.NoError(t, json.Unmarshal(raw, &installed))

	state, err := codexHookTrustState(dir)
	require.NoError(t, err)

	known := make(map[string]string, len(codex.HookEventSpecs()))
	for _, ev := range codex.HookEventSpecs() {
		known[ev.Event] = ev.Label
	}

	for event, groups := range installed.Hooks {
		for _, group := range groups {
			for _, handler := range group.Hooks {
				if !strings.Contains(handler.Command, "entire hooks codex") {
					continue
				}
				label, ok := known[event]
				require.Truef(t, ok, "Codex event metadata has no entry for %s: the CLI installs it, so e2e leaves it untrusted and Codex never fires it", event)
				require.Containsf(t, state, label+":", "no trusted_hash generated for %s", event)

				// The hash is computed over the configured timeout, while Codex
				// caps SessionEnd handlers at SESSION_END_MAX_TIMEOUT_SEC. If it
				// applies that clamp before hashing, anything above the ceiling
				// would hash differently here and leave session_end untrusted —
				// silently, since an untrusted hook simply never fires. Installing
				// exactly the ceiling keeps both orderings identical, so pin it.
				if event == "SessionEnd" {
					require.NotNilf(t, handler.Timeout, "SessionEnd handler has no timeout; expected the %ds ceiling", codex.SessionEndTimeoutSec)
					require.EqualValuesf(t, codex.SessionEndTimeoutSec, *handler.Timeout,
						"SessionEnd installed above Codex's clamp ceiling: the pre-trust hash here may no longer match what Codex computes, which would leave the hook untrusted and silently dead in e2e")
				}
			}
		}
	}
}

// TestCodexHookTrustState_MissingFileIsNoop returns empty trust state
// (and no error) when there's no hooks.json yet — the e2e seed runs
// before some tests' enable step.
func TestCodexHookTrustState_MissingFileIsNoop(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	state, err := codexHookTrustState(dir)
	require.NoError(t, err)
	require.Empty(t, state)
}
package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "copilot-cli" {
		return
	}
	Register(&CopilotCLI{})
	RegisterGate("copilot-cli", 4)
}

type CopilotCLI struct{}

func (c *CopilotCLI) Name() string               { return "copilot-cli" }
func (c *CopilotCLI) Binary() string             { return "copilot" }
func (c *CopilotCLI) EntireAgent() string        { return "copilot-cli" }
func (c *CopilotCLI) PromptPattern() string      { return `❯` }
func (c *CopilotCLI) TimeoutMultiplier() float64 { return 1.5 }

func (c *CopilotCLI) IsTransientError(out Output, err error) bool {
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{
		"overloaded",
		"rate limit",
		"503",
		"529",
		"ECONNRESET",
		"ETIMEDOUT",
		"Too Many Requests",
		// Copilot sometimes calls its Edit tool without old_str,
		// resulting in zero code changes despite a successful exit.
		"old_str is required",
	} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (c *CopilotCLI) Bootstrap() error {
	// Copilot CLI uses GitHub authentication (gh auth or GITHUB_TOKEN).
	// No additional bootstrap needed — auth should be pre-configured.
	return nil
}

func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{Model: "claude-haiku-4.5"}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 60 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}
	promptCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	// GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS opts in to .github/hooks/*.json loading
	// in -p mode; gated since Copilot 1.0.40 (2026-05-01).
	cmd.Env = append(os.Environ(),
		"ENTIRE_TEST_TTY=0",
		"GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS=true",
	)
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	exitCode, err := runCapture(cmd, promptCtx)

	out := Output{
		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}

	// Copilot sometimes calls its Edit tool without required parameters,
	// producing zero code changes despite exit 0. Surface this as an error so
	// the transient-error retry mechanism can restart the scenario.
	// Only trigger when copilot reports zero changes — it may retry internally.
	if err == nil && strings.Contains(out.Stdout, "old_str is required") &&
		strings.Contains(out.Stderr, "Total code changes:     +0 -0") {
		err = errors.New("copilot Edit tool failed: old_str is required")
	}

	return out, err
}

// CopilotSession wraps TmuxSession to handle Copilot CLI's dual input modes.
// Copilot CLI can be in "Chat" mode (Enter submits) or "Edit" mode (Ctrl+S
// submits). After completing a prompt, copilot may return to either mode
// non-deterministically. This wrapper detects Edit mode after sending Enter
// and falls back to Ctrl+S if needed.
type CopilotSession struct {
	*TmuxSession
}

func (cs *CopilotSession) Send(input string) error {
	if err := cs.clearInputLine(); err != nil {
		return err
	}

	preSend := stableContent(cs.Capture())

	if err := cs.sendOnce(input, preSend); err != nil {
		return err
	}

	// Copilot CLI's autocomplete can non-deterministically trigger during
	// text input (e.g. a "/" in "docs/red.md" opens the slash-command menu).
	// If detected, dismiss with Escape, clear the input, and retry once.
	time.Sleep(300 * time.Millisecond)
	if isAutocompleteMenu(cs.Capture()) {
		if err := cs.dismissAutocompleteAndClear(); err != nil {
			return err
		}
		if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
			return err
		}
	}

	// Copilot can leave behind a stray slash-command invocation between turns.
	// Only retry if that error appeared in output produced by this submission,
	// not merely somewhere in pane scrollback from an earlier turn.
	if content := cs.Capture(); appearedInNewOutput(preSend, content, "Unknown command: /") {
		if err := cs.clearInputLine(); err != nil {
			return err
		}
		if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
			return err
		}
	}

	// Wait for the terminal to reflect the echoed input, then snapshot.
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		time.Sleep(200 * time.Millisecond)
		current := stableContent(cs.Capture())
		if current != preSend {
			cs.stableAtSend = current
			return nil
		}
	}
	cs.stableAtSend = stableContent(cs.Capture())
	return nil
}

// clearInputLine removes any partially typed prompt text without sending other
// UI navigation keys. In Copilot CLI, Escape can trigger undo/snapshot actions,
// so routine pre-send cleanup must avoid it.
func (cs *CopilotSession) clearInputLine() error {
	if err := cs.SendKeys("C-u"); err != nil {
		return err
	}
	time.Sleep(200 * time.Millisecond)
	return nil
}

// dismissAutocompleteAndClear closes the slash-command autocomplete dropdown
// and then clears the input line before retrying the prompt.
func (cs *CopilotSession) dismissAutocompleteAndClear() error {
	if err := cs.SendKeys("Escape"); err != nil {
		return err
	}
	time.Sleep(200 * time.Millisecond)
	return cs.clearInputLine()
}

// appearedInNewOutput reports whether pattern is present in content that was
// added after the pre-send snapshot. This avoids retriggering on old pane
// scrollback from previous turns.
func appearedInNewOutput(before string, after string, pattern string) bool {
	if after == before {
		return false
	}
	if strings.HasPrefix(after, before) {
		return strings.Contains(after[len(before):], pattern)
	}

	// If tmux capture lost a clean prefix relationship due to scrollback churn,
	// fall back to checking only the most recent lines.
	lines := strings.Split(after, "\n")
	start := max(0, len(lines)-12)
	return strings.Contains(strings.Join(lines[start:], "\n"), pattern)
}

// sendOnce types the input text, sends Enter, and handles Edit mode fallback.
func (cs *CopilotSession) sendOnce(input string, preSend string) error {
	// Use -l (literal) flag to prevent tmux from interpreting characters
	// in the prompt text as special key names.
	args := []string{"send-keys", "-l", "-t", cs.name, input}
	cmd := exec.Command("tmux", args...)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("tmux send-keys -l: %w\n%s", err, out)
	}
	time.Sleep(200 * time.Millisecond)
	if err := cs.SendKeys("Enter"); err != nil {
		return err
	}

	// Briefly poll to see if copilot is still in Edit mode (Enter didn't submit).
	// In Edit mode the status bar shows "ctrl+s run command". If detected,
	// send Ctrl+S to actually submit the prompt. Break early if the content
	// changes from the pre-send snapshot, indicating submission has started.
	editDeadline := time.Now().Add(500 * time.Millisecond)
	for time.Now().Before(editDeadline) {
		content := cs.Capture()
		if isEditMode(content) {
			if err := cs.SendKeys("C-s"); err != nil {
				return err
			}
			break
		}
		if stableContent(content) != preSend {
			break
		}
		time.Sleep(50 * time.Millisecond)
	}
	return nil
}

// isEditMode checks if copilot-cli is in Edit mode by looking for the
// "ctrl+s run command" indicator in the last few lines (status bar area).
// Restricting the search avoids false positives if the phrase appears in
// agent output.
func isEditMode(content string) bool {
	lines := strings.Split(content, "\n")
	const statusPhrase = "ctrl+s run command"
	for i := len(lines) - 1; i >= 0 && i >= len(lines)-3; i-- {
		if strings.Contains(lines[i], statusPhrase) {
			return true
		}
	}
	return false
}

// isAutocompleteMenu detects copilot's slash-command autocomplete dropdown.
// When triggered, copilot shows a list of commands starting with "▋  /"
// below the input line, preventing prompt submission.
func isAutocompleteMenu(content string) bool {
	lines := strings.Split(content, "\n")
	matches := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "▋") && strings.Contains(trimmed, "/") {
			matches++
			if matches >= 2 {
				return true
			}
		}
	}
	return false
}

// isStartupDialog reports whether the captured pane is showing a Copilot
// startup dialog (e.g. "Confirm folder trust") rather than the interactive
// prompt. The dialog renders its selected option with the same "❯" cursor as
// the input prompt, so presence of "❯" alone cannot distinguish them — we must
// key off the dialog chrome.
//
// Matching is case-insensitive and keyed off both the dialog title and its
// footer: Copilot v1.0.63 lowercased the footer to "enter to select", which
// silently broke the previous exact "Enter to select" match and caused the
// harness to mistake the trust dialog's "❯ 1. Yes" cursor for the prompt —
// breaking out of the dismissal loop without dismissing the dialog, so the
// first real prompt was swallowed by the still-open dialog.
func isStartupDialog(content string) bool {
	lower := strings.ToLower(content)
	return strings.Contains(lower, "confirm folder trust") ||
		strings.Contains(lower, "do you trust") ||
		strings.Contains(lower, "enter to select")
}

func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	bin, err := exec.LookPath(c.Binary())
	if err != nil {
		return nil, fmt.Errorf("agent binary not found: %w", err)
	}

	// Forward auth-related env vars into the tmux session. tmux starts a new
	// shell that doesn't inherit Go's os.Environ(), so without this the
	// session can lose both token-based auth and local gh/copilot login state.
	var envArgs []string
	for _, key := range []string{"COPILOT_GITHUB_TOKEN", "HOME", "TERM", "XDG_CONFIG_HOME", "GH_CONFIG_DIR"} {
		if v := os.Getenv(key); v != "" {
			envArgs = append(envArgs, key+"="+v)
		}
	}
	args := append([]string{"env"}, envArgs...)
	args = append(args, bin, "--model", "claude-haiku-4.5", "--allow-all")

	name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
	// Strip CI env vars that may affect interactive mode.
	unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
	if err != nil {
		return nil, err
	}

	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
	// new directories. "Yes" is pre-selected, so Enter dismisses it.
	foundPrompt := false
	for range 5 {
		content, err := s.WaitFor(`(❯|(?i:enter to select))`, 30*time.Second)
		if err != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
		}
		if strings.Contains(content, "❯") && !isStartupDialog(content) {
			foundPrompt = true
			break
		}
		if err := s.SendKeys("Enter"); err != nil {
			_ = s.Close()
			return nil, fmt.Errorf("dismissing startup dialog: %w", err)
		}
		time.Sleep(500 * time.Millisecond)
	}
	if !foundPrompt {
		_ = s.Close()
		return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
	}
	s.stableAtSend = ""

	return &CopilotSession{TmuxSession: s}, nil
}
